var incidence = function(image){

  var imc = tf_lib.toImageCollection(image);

  var imagefirst = ee.Image(imc.first());

  imagefirst = imagefirst.addBands(ee.Image(0)).rename(["classification", "incidence"]);

  var result = ee.Image(imc.iterate(function(img, prev){

    img = ee.Image(img);

    prev = ee.Image(prev);

    var imgincidence = prev.select(["incidence"]);

    var classification0 = prev.select(["classification"]);

    var classification1 = img.select(["classification"]);

    var change  = ee.Image(0);

    change = change.where(classification0.neq(classification1), 1);

    imgincidence = imgincidence.where(change.eq(1), imgincidence.add(1));

    return img.addBands(imgincidence);

  }, imagefirst)

  ).select(["incidence"]);

  return result;

};

